  for (let c = 0; c < cols; c += 1) if (matrix[0][c] === 0) row0 = true;
  for (let r = 0; r < rows; r += 1) if (matrix[r][0] === 0) col0 = true;
  for (let r = 1; r < rows; r += 1) {
    for (let c = 1; c < cols; c += 1) {
      if (matrix[r][c] === 0) {
        matrix[r][0] = 0;
        matrix[0][c] = 0;
      }
    }
  }
  for (let r = 1; r < rows; r += 1) {
    for (let c = 1; c < cols; c += 1) {
      if (matrix[r][0] === 0 || matrix[0][c] === 0) matrix[r][c] = 0;
    }
  }
  if (row0) for (let c = 0; c < cols; c += 1) matrix[0][c] = 0;
  if (col0) for (let r = 0; r < rows; r += 1) matrix[r][0] = 0;
  return matrix;
}

function xorAll(nums) {
  return nums.reduce((a, b) => a ^ b, 0);
}

function hammingWeight(n) {
  let count = 0;
  while (n) {
    n &= n - 1;
    count += 1;
  }
  return count;
}

function countBits(n) {
  const ans = Array(n + 1).fill(0);
  for (let i = 1; i <= n; i += 1) ans[i] = ans[i >> 1] + (i & 1);
  return ans;
}

function reverseBits(n) {
  let res = 0;
  for (let i = 0; i < 32; i += 1) {
    res = (res << 1) | (n & 1);
    n >>>= 1;
  }
  return res >>> 0;
}

function missingNumber(nums) {
  let xor = nums.length;
  for (let i = 0; i < nums.length; i += 1) xor ^= i ^ nums[i];
  return xor;
}

function getSum(a, b) {
  while (b !== 0) {
    const carry = (a & b) << 1;
    a = a ^ b;
    b = carry;
  }
  return a | 0;
}
